cards.css:
:root {
  --warna-utama: #4361ee;
  --warna-latar: #f8f9fa;
  --warna-kartu: #ffffff;
  --warna-teks: #212529;
  --radius: 8px;
}

body {
  background-color: var(--warna-latar);
  color: var(--warna-teks);
  font-family: sans-serif;
  margin: 0;
}

main {
  background-color: var(--warna-kartu);
  border-radius: var(--radius);
  padding: 20px;
  margin: 40px auto;
  max-width: 400px;
}

